function fewestDeletionBalances(s: string): string[] {
  const idx: number[] = [];
  for (let i = 0; i < s.length; i++) if (s[i] === "(" || s[i] === ")") idx.push(i);
  const balanced = (t: string) => {
    let open = 0;
    for (const c of t) {
      if (c === "(") open++;
      else if (c === ")" && --open < 0) return false;
    }
    return open === 0;
  };
  let best = Infinity;
  let found = new Set<string>();
  for (let mask = 0; mask < 1 << idx.length; mask++) {
    let bits = 0;
    for (let m = mask; m; m &= m - 1) bits++;
    if (bits > best) continue;
    const drop = new Set<number>();
    idx.forEach((p, k) => { if (mask >> k & 1) drop.add(p); });
    let t = "";
    for (let i = 0; i < s.length; i++) if (!drop.has(i)) t += s[i];
    if (!balanced(t)) continue;
    if (bits < best) { best = bits; found = new Set(); }
    found.add(t);
  }
  return [...found];
}

