function fewestDeletionBalances(s: string): string[] {
  const balanced = (t: string) => {
    let open = 0;
    for (const c of t) {
      if (c === "(") open++;
      else if (c === ")" && --open < 0) return false;
    }
    return open === 0;
  };
  let level = new Set([s]);
  while (true) {
    const good = [...level].filter(balanced);
    if (good.length) return good;
    const next = new Set<string>();
    for (const t of level) {
      for (let i = 0; i < t.length; i++) {
        if (t[i] !== "(" && t[i] !== ")") continue;
        if (i > 0 && t[i] === t[i - 1]) continue; // same result as deleting t[i-1]
        next.add(t.slice(0, i) + t.slice(i + 1));
      }
    }
    level = next;
  }
}

