function fewestDeletionBalances(s: string): string[] {
  let rmOpen = 0, rmClose = 0;
  for (const c of s) {
    if (c === "(") rmOpen++;
    else if (c === ")") { if (rmOpen > 0) rmOpen--; else rmClose++; }
  }
  const out = new Set<string>();
  const built: string[] = [];
  const go = (i: number, open: number, ro: number, rc: number): void => {
    if (i === s.length) {
      if (open === 0 && ro === 0 && rc === 0) out.add(built.join(""));
      return;
    }
    const c = s[i];
    if (c === "(" && ro > 0) go(i + 1, open, ro - 1, rc);
    if (c === ")" && rc > 0) go(i + 1, open, ro, rc - 1);
    if (c === ")" && open === 0) return; // cannot keep it
    built.push(c);
    go(i + 1, open + (c === "(" ? 1 : c === ")" ? -1 : 0), ro, rc);
    built.pop();
  };
  go(0, 0, rmOpen, rmClose);
  return [...out];
}

