                rm_open += 1
            elif c == ")":
                if rm_open:
                    rm_open -= 1
                else:
                    rm_close += 1
        out = set()
        built = []

        def go(i, open_, ro, rc):
            if i == len(s):
                if open_ == 0 and ro == 0 and rc == 0:
                    out.add("".join(built))
                return
            c = s[i]
            if c == "(" and ro:
                go(i + 1, open_, ro - 1, rc)
            if c == ")" and rc:
                go(i + 1, open_, ro, rc - 1)
            if c == ")" and open_ == 0:
                return  # cannot keep it
            built.append(c)
            go(i + 1, open_ + (c == "(") - (c == ")"), ro, rc)
            built.pop()

        go(0, 0, rm_open, rm_close)
        return list(out)

